use super::*;use std::sync::Mutex;use std::collections::BTreeMap;
#[derive(Default)]struct Memory{data:Mutex<BTreeMap<(String,String,uuid::Uuid),Vec<u8>>>,writes:Mutex<(usize,Option<usize>)>}
impl CredentialStore for Memory{
 fn save(&self,p:&ServiceProfile,b:&SecretBlob)->Result<(),crate::secrets::StoreError>{let mut n=self.writes.lock().unwrap();n.0+=1;if n.1==Some(n.0){return Err(crate::secrets::StoreError::Unavailable)}self.data.lock().unwrap().insert((p.origin().into(),p.service_id().into(),p.profile_id()),b.bytes().to_vec());Ok(())}
 fn load(&self,p:&ServiceProfile)->Result<Option<SecretBlob>,crate::secrets::StoreError>{self.data.lock().unwrap().get(&(p.origin().into(),p.service_id().into(),p.profile_id())).map(|v|SecretBlob::new(v.clone())).transpose()}
 fn delete(&self,p:&ServiceProfile)->Result<(),crate::secrets::StoreError>{self.data.lock().unwrap().remove(&(p.origin().into(),p.service_id().into(),p.profile_id()));Ok(())}
}
